update public.article_cache set translation = '{"texts": ["Southwest Airlines announced it will ban humanoid robots and robot pets from boarding flights, with this decision made due to safety concerns rather than the robots'' personalities or behavior.", "The airline''s main concern is lithium-ion batteries, which are necessary for robot operation but can pose risks to aircraft safety.", "Southwest Airlines explained that it created this policy by prioritizing passenger safety above all else, and other airlines are expected to be considering similar measures.", "Passengers wanting to travel with robots must now use other transportation methods or travel without their robots, as the aviation industry continues updating safety regulations for new technologies."], "sentences": [{"text": "미국 사우스웨스트 항공이 휴머노이드 로봇과 로봇 애완동물의 비행기 탑승을 금지한다고 발표했어요.", "translation": "Southwest Airlines announced it will ban humanoid robots and robot pets from boarding flights.", "vocab": [{"ko": "항공", "en": "airline; aviation", "note": ""}, {"ko": "휴머노이드", "en": "humanoid", "note": "human-like robot"}, {"ko": "애완동물", "en": "pet", "note": ""}, {"ko": "탑승", "en": "boarding", "note": "getting on a vehicle"}], "analysis": [{"type": "grammar", "label": "~다고 발표하다", "exp": "Reports what was announced: ''announce that ~''. 금지하다 → 금지한다고 발표했어요 (announced that it will ban).", "example_in_sentence": "금지한다고 발표했어요"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "past polite. 발표하다 (announce) → 발표했어요 (announced)", "example_in_sentence": "발표했어요"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "with / and (formal)", "example_in_sentence": "로봇과"}]}, {"text": "이번 결정은 로봇의 성격이나 행동 때문이 아니라 안전 문제 때문에 내려졌어요.", "translation": "This decision was made due to safety concerns rather than the robots'' personalities or behavior.", "vocab": [{"ko": "결정", "en": "decision", "note": ""}, {"ko": "성격", "en": "personality, character", "note": ""}, {"ko": "행동", "en": "behavior, conduct", "note": ""}, {"ko": "안전", "en": "safety", "note": ""}], "analysis": [{"type": "grammar", "label": "~(이)나", "exp": "or / about / as much as. 성격이나 행동 (personality or behavior)", "example_in_sentence": "성격이나 행동"}, {"type": "grammar", "label": "~아/어지다", "exp": "passive / become. 내리다 (make/drop) → 내려지다 → 내려졌어요 (was made)", "example_in_sentence": "내려졌어요"}, {"type": "expression", "label": "~ 때문에", "exp": "because of N. Shows cause or reason with noun", "example_in_sentence": "안전 문제 때문에"}]}, {"text": "항공사가 가장 우려하는 것은 리튬이온 배터리예요.", "translation": "The airline''s main concern is lithium-ion batteries.", "vocab": [{"ko": "항공사", "en": "airline", "note": ""}, {"ko": "우려하다", "en": "worry, be concerned", "note": ""}, {"ko": "배터리", "en": "battery", "note": ""}], "analysis": [{"type": "grammar", "label": "~는 것", "exp": "Turns a verb phrase into a noun: ''what one ~s''. 우려하다 → 우려하는 것 (what it worries about).", "example_in_sentence": "우려하는 것"}]}, {"text": "이 배터리는 로봇이 작동하는 데 필요하지만 항공기 운항에 위험을 줄 수 있어요.", "translation": "These batteries are needed for robots to operate, but they can pose a risk to flights.", "vocab": [{"ko": "작동하다", "en": "operate, function", "note": ""}, {"ko": "필요하다", "en": "necessary, needed", "note": ""}, {"ko": "항공기", "en": "aircraft", "note": ""}, {"ko": "운항", "en": "flight operation", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/는 데(에)", "exp": "in V-ing / for V-ing. 작동하는 데 (for operating)", "example_in_sentence": "작동하는 데"}, {"type": "grammar", "label": "~지만", "exp": "but / although. Shows contrast between clauses", "example_in_sentence": "필요하지만"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다/없다", "exp": "ability/possibility. 주다 (give) → 줄 수 있어요 (can give/pose)", "example_in_sentence": "줄 수 있어요"}]}, {"text": "사우스웨스트 항공은 승객의 안전을 최우선으로 고려해서 이런 정책을 만들었다고 설명했어요.", "translation": "Southwest Airlines explained that it created this policy by prioritizing passenger safety above all else.", "vocab": [{"ko": "승객", "en": "passenger", "note": ""}, {"ko": "최우선", "en": "top priority", "note": ""}, {"ko": "고려하다", "en": "consider", "note": ""}, {"ko": "정책", "en": "policy", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로", "exp": "means/direction. 최우선으로 (as top priority / prioritizing)", "example_in_sentence": "최우선으로"}, {"type": "grammar", "label": "~아/어서", "exp": "cause / sequence. 고려하다 (consider) → 고려해서 (by considering)", "example_in_sentence": "고려해서"}, {"type": "grammar", "label": "~다고 설명하다", "exp": "Reports an explanation: ''explain that ~''. 만들다 → 만들었다고 설명했어요 (explained that it made).", "example_in_sentence": "만들었다고 설명했어요"}, {"type": "expression", "label": "최우선으로 고려하다", "exp": "prioritize above all / consider as top priority", "example_in_sentence": "최우선으로 고려해서"}]}, {"text": "다른 항공사들도 비슷한 조치를 검토하고 있을 것으로 예상돼요.", "translation": "Other airlines are expected to be considering similar measures.", "vocab": [{"ko": "비슷하다", "en": "similar", "note": ""}, {"ko": "조치", "en": "measure, action", "note": ""}, {"ko": "검토하다", "en": "review, consider", "note": ""}, {"ko": "예상되다", "en": "to be expected", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "continuous. 검토하다 (review) → 검토하고 있다 (is reviewing)", "example_in_sentence": "검토하고 있을"}, {"type": "grammar", "label": "~(으)ㄹ 것으로 예상되다", "exp": "''Is expected to ~'', common in news. 검토하고 있다 → 검토하고 있을 것으로 예상돼요 (are expected to be reviewing).", "example_in_sentence": "있을 것으로 예상돼요"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "Many 하다 verbs become passive with 되다. 예상하다 (expect) → 예상되다 → 예상돼요 (is expected).", "example_in_sentence": "예상돼요"}]}, {"text": "이제 로봇을 가지고 여행하려는 승객들은 다른 교통수단을 이용하거나 로봇 없이 여행해야 해요.", "translation": "Passengers wanting to travel with robots must now use other transportation methods or travel without their robots.", "vocab": [{"ko": "가지다", "en": "have, bring", "note": ""}, {"ko": "여행하다", "en": "travel", "note": ""}, {"ko": "교통수단", "en": "transportation method", "note": ""}, {"ko": "이용하다", "en": "use, utilize", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)려는 N", "exp": "Modifier form of ~(으)려고 하다: ''who intend to ~''. 여행하다 → 여행하려는 승객들 (passengers who want to travel).", "example_in_sentence": "여행하려는"}, {"type": "grammar", "label": "~거나", "exp": "or. Shows choice between options", "example_in_sentence": "이용하거나"}, {"type": "grammar", "label": "~아/어야 하다/되다", "exp": "must / have to. 하다 → 해야 해요 (must do)", "example_in_sentence": "여행해야 해요"}]}, {"text": "항공업계에서는 새로운 기술에 대한 안전 규정을 계속 업데이트하고 있어요.", "translation": "The aviation industry continues updating safety regulations for new technologies.", "vocab": [{"ko": "항공업계", "en": "aviation industry", "note": ""}, {"ko": "새롭다", "en": "new", "note": ""}, {"ko": "기술", "en": "technology", "note": ""}, {"ko": "규정", "en": "regulation, rule", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 대한 N", "exp": "about/regarding N (adnominal). 기술에 대한 규정 (regulations regarding technology)", "example_in_sentence": "기술에 대한 안전 규정"}, {"type": "grammar", "label": "~고 있다", "exp": "continuous. 업데이트하다 → 업데이트하고 있어요 (is updating)", "example_in_sentence": "업데이트하고 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "항공", "en": "airline; aviation", "note": ""}, {"ko": "휴머노이드", "en": "humanoid", "note": "human-like robot"}, {"ko": "애완동물", "en": "pet", "note": ""}, {"ko": "탑승", "en": "boarding", "note": "getting on a vehicle"}, {"ko": "결정", "en": "decision", "note": ""}, {"ko": "성격", "en": "personality, character", "note": ""}, {"ko": "행동", "en": "behavior, conduct", "note": ""}, {"ko": "안전", "en": "safety", "note": ""}, {"ko": "항공사", "en": "airline", "note": ""}, {"ko": "우려하다", "en": "worry, be concerned", "note": ""}, {"ko": "배터리", "en": "battery", "note": ""}, {"ko": "작동하다", "en": "operate, function", "note": ""}, {"ko": "필요하다", "en": "necessary, needed", "note": ""}, {"ko": "항공기", "en": "aircraft", "note": ""}, {"ko": "운항", "en": "flight operation", "note": ""}, {"ko": "승객", "en": "passenger", "note": ""}, {"ko": "최우선", "en": "top priority", "note": ""}, {"ko": "고려하다", "en": "consider", "note": 